function getRectangleRotationAngle(coords) {
    // EPSG:3857 constants
    const RADIUS = 6378137;

    // Перетворення з lat/lon в метри за проекцією Web Mercator
    function toWebMercator([lat, lon]) {
        const x = RADIUS * lon * Math.PI / 180;
        const y = RADIUS * Math.log(Math.tan(Math.PI / 4 + lat * Math.PI / 360));
        return [x, y];
    }

    // Евклідова відстань
    function distance(p1, p2) {
        const dx = p2[0] - p1[0];
        const dy = p2[1] - p1[1];
        return Math.sqrt(dx * dx + dy * dy);
    }

    // Проєктуємо всі координати
    const projected = coords.map(toWebMercator);

    // Знаходимо найдовшу сторону
    let maxDist = 0;
    let edge = [0, 1];
    for (let i = 0; i < projected.length; i++) {
        const j = (i + 1) % projected.length;
        const d = distance(projected[i], projected[j]);
        if (d > maxDist) {
            maxDist = d;
            edge = [i, j];
        }
    }

    const [p1, p2] = [projected[edge[0]], projected[edge[1]]];
    const dx = p2[0] - p1[0];
    const dy = p2[1] - p1[1];
    const angleRad = Math.atan2(dy, dx);
    const angleDeg = angleRad * 180 / Math.PI;

    return angleDeg; // Повертає кут у градусах, може бути від -180 до +180
}

